output_text:
[
  {
    "id": "items_must_go_in_cart",
    "text": "Required items may not be picked up unless the shopper is currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "keep_hands_free",
    "text": "The shopper must not walk around the store while carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "move_with_hand_item": {
          "pre": {
            "and": [
              "MOVE",
              "carrying_by_hand"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_with_hand_item"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the front cart-return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_parked_in_front_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "front_return_bay"
            ]
          },
          "post": "cart_parked_in_front_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "A cart may only be left at the designated front cart-return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The shopper is prohibited from exiting the supermarket while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_free_exit_aisle",
    "text": "Carts are not allowed on the bottom exit aisle beyond the cart rack, so shoppers must leave the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_aisle": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_possession_on_exit_aisle": {
          "and": [
            "hasCart",
            "bottom_exit_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_possession_on_exit_aisle"
    }
  },
  {
    "id": "no_southbound_cart_traffic",
    "text": "Shopping carts may not be moved southward through the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "south_move_with_cart": {
          "pre": {
            "and": [
              "S",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "south_move_with_cart"
    }
  },
  {
    "id": "east_section_before_west_check",
    "text": "After collecting an item from the eastern part of the product aisle, the shopper must collect or check an item station in the western part of that aisle before leaving.",
    "abstraction": {
      "state_properties": {
        "eastern_product_section": {
          "or": [
            "at(5,2)",
            "at(6,2)"
          ]
        },
        "western_product_section": {
          "or": [
            "at(2,2)",
            "at(3,2)"
          ]
        }
      },
      "events": {
        "pickup_in_eastern_section": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "eastern_product_section"
            ]
          },
          "post": null
        },
        "pickup_in_western_section": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "western_product_section"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_in_eastern_section",
      "discharge": "pickup_in_western_section"
    }
  }
]
